// The vendor bundle (cli/lib/bundle.mjs, vendor.mjs) and the render hash
// (hash.mjs). The bundle is byte-identical across runs and checkouts and
// follows the load order of DESIGN.md. The hash is stable, changes with the
// episode, a lexicon entry its lines use and a library file its bundle
// includes, and ignores unused lexicon entries, other library files and
// generated files. The hash needs Python for the voice tool's keys.
import assert from "node:assert/strict";
import { appendFileSync, mkdirSync, readFileSync, rmSync, writeFileSync } from "node:fs";
import path from "node:path";
import { after, before, describe, test } from "node:test";
import { pathToFileURL } from "node:url";
import { bundleCss, bundleFiles, bundleJs, dataOf, writeVendor } from "../cli/lib/bundle.mjs";
import { episodeFiles } from "../cli/lib/hash.mjs";
import { BUILTIN_SCENES, loadProject, resolveEpisode } from "../cli/lib/project.mjs";
import { refreshVendor, vendorFresh } from "../cli/lib/vendor.mjs";
import { DEMO, REPO, copyPackage, copyProject, fixture, outputOf, pythonAvailable, runCli, suiteDir, tempDir, walkFiles } from "./helpers.mjs";

const HAS_PYTHON = pythonAvailable();
const read = (root, rel) => readFileSync(path.join(root, rel));
// Every file of an episode's vendor/ with its bytes (walked from inside,
// because walkFiles leaves generated directories such as vendor/ out).
const vendorOf = (dir) => Object.fromEntries(walkFiles(path.join(dir, "vendor")).map((f) => [f, read(path.join(dir, "vendor"), f)]));

describe("bundle", () => {
  const studio = loadProject(fixture("studio"));

  test("avatars.js loads the data block, the core, the cast's rig, base and parts, then scenes and highlighters", () => {
    const r = resolveEpisode(studio, "basic");
    const js = bundleJs(r);
    assert.match(js, /^\/\/ Generated by `avatars vendor`/);
    assert.ok(js.indexOf("A.data = ") < js.indexOf("// ---- core/determinism.js"), "the data block first");
    const labels = [...js.matchAll(/^\/\/ ---- (.+)$/gm)].map((m) => m[1]);
    const highlighters = labels.filter((l) => l.startsWith("scenes/code/highlight/"));
    assert.deepEqual(labels, [
      "core/determinism.js", "core/tokens.js", "core/planner.js", "core/clock.js", "core/captions.js", "core/transitions.js", "core/stage.js", "core/performer.js",
      "rigs/svg/rig.js",
      "project:library/rigs/svg/bases/box-200x200/base.js",
      ...r.cast.host.parts.map((p) => (p.id.startsWith("kit/") ? `project:library/avatars/kit/parts/${p.id.slice(4)}/part.js` : `project:library/parts/${p.id}/part.js`)),
      "core/presenter.js", "core/episode.js",
      ...BUILTIN_SCENES.map((s) => `scenes/${s}/${s}.js`), "project:library/scenes/callout/callout.js",
      ...highlighters,
    ]);
    assert.deepEqual(highlighters, [...highlighters].sort());
    assert.ok(highlighters.includes("scenes/code/highlight/text.js"), "the fallback highlighter");
  });

  test("the data block is Avatars.data as plain JSON", () => {
    const r = resolveEpisode(studio, "basic");
    const m = /A\.data = (.+);\n/.exec(bundleJs(r));
    assert.deepEqual(JSON.parse(m[1]), JSON.parse(JSON.stringify(dataOf(r))));
    assert.deepEqual(Object.keys(dataOf(r)), ["tokens", "format", "brand", "icons", "cast", "bases", "parts"]);
  });

  test("avatars.css holds the tokens on :root, then core, scene and format CSS", () => {
    const r = resolveEpisode(studio, "basic");
    const css = bundleCss(r);
    assert.ok(css.indexOf(":root {\n  --av-") < css.indexOf("/* ---- core/core.css */"), "tokens first");
    assert.match(css, /^ {2}--av-color-accent: #a00000;$/m);
    assert.match(css, /^ {2}--av-callout-accent: rgba\(160, 0, 0, 0\.5\);$/m);
    const labels = [...css.matchAll(/^\/\* ---- (.+) \*\/$/gm)].map((m) => m[1]);
    assert.deepEqual(labels, ["core/core.css", ...BUILTIN_SCENES.map((s) => `scenes/${s}/${s}.css`), "project:library/scenes/callout/callout.css"]);
  });

  test("vendor/ holds avatars.js, avatars.css, GSAP and the theme's fonts", () => {
    const r = resolveEpisode(loadProject(DEMO), "tour");
    const names = bundleFiles(r).map(([rel]) => rel);
    assert.deepEqual(names, ["avatars.js", "avatars.css", "gsap.min.js", ...r.theme.fonts.map((f) => `fonts/${f.file}`)]);
  });

  test("the bundle names no path of the checkout", () => {
    const r = resolveEpisode(studio, "basic");
    for (const text of [bundleJs(r), bundleCss(r)]) {
      // The fixture project lies inside the package checkout.
      assert.ok(!text.includes(REPO), "no path of the package or the project");
    }
  });

  test("refreshVendor rewrites a stale vendor/ and leaves a fresh one alone", (t) => {
    const root = copyProject(fixture("studio"), path.join(tempDir(t), "studio"));
    const r = resolveEpisode(loadProject(root), "basic");
    assert.equal(vendorFresh(r.dir, bundleFiles(r)), false, "no vendor/ yet");
    assert.equal(refreshVendor(r), true);
    assert.equal(refreshVendor(r), false, "fresh");
    appendFileSync(path.join(r.dir, "vendor", "avatars.css"), "/* edited */\n");
    assert.equal(refreshVendor(r), true, "an edited file");
    writeFileSync(path.join(r.dir, "vendor", "extra.js"), "");
    assert.equal(vendorFresh(r.dir, bundleFiles(r)), false, "an extra file");
    writeVendor(r.dir, bundleFiles(r));
    assert.equal(vendorFresh(r.dir, bundleFiles(r)), true, "writeVendor replaces the directory");
  });
});

describe("vendor output across runs and checkouts", () => {
  const tmp = suiteDir(before, after, "avatars-vendor-");
  let a;
  let b;
  before(() => {
    // Two checkouts of the package and of the demo project, at different depths and names.
    a = { pkg: copyPackage(path.join(tmp.path, "a", "avatars")), project: copyProject(DEMO, path.join(tmp.path, "a", "demo")) };
    b = { pkg: copyPackage(path.join(tmp.path, "b", "src", "lib-checkout")), project: copyProject(DEMO, path.join(tmp.path, "b", "work", "my-demo")) };
  });
  const vendor = (c) => {
    const r = runCli(["vendor", "--all", "--project", c.project], { cli: path.join(c.pkg, "cli", "avatars.mjs") });
    assert.equal(r.status, 0, outputOf(r));
    const out = {};
    for (const id of ["tour", "wardrobe"]) out[id] = vendorOf(path.join(c.project, "episodes", id));
    return out;
  };

  test("is byte-identical across two runs and two checkout paths", () => {
    const first = vendor(a);
    const again = vendor(a);
    const other = vendor(b);
    for (const id of ["tour", "wardrobe"]) {
      assert.ok(Object.keys(first[id]).length >= 4, `${id}: ${Object.keys(first[id]).join(", ")}`);
      assert.deepEqual(Object.keys(again[id]), Object.keys(first[id]));
      assert.deepEqual(Object.keys(other[id]), Object.keys(first[id]));
      for (const f of Object.keys(first[id])) {
        assert.ok(first[id][f].equals(again[id][f]), `${id}/vendor/${f} differs between runs`);
        assert.ok(first[id][f].equals(other[id][f]), `${id}/vendor/${f} differs between checkouts`);
      }
    }
  });
});

describe("render hash", { skip: HAS_PYTHON ? false : "needs python3 (or AVATARS_PYTHON) for the voice tool's keys" }, () => {
  const tmp = suiteDir(before, after, "avatars-hash-");
  let a;
  let b;
  let lib;
  const ID = "wardrobe";
  before(async () => {
    a = { pkg: copyPackage(path.join(tmp.path, "a", "avatars")), project: copyProject(DEMO, path.join(tmp.path, "a", "demo")) };
    b = { pkg: copyPackage(path.join(tmp.path, "b", "deeper", "pkg")), project: copyProject(DEMO, path.join(tmp.path, "b", "elsewhere", "demo-copy")) };
    // The modules of checkout a, so its PKG is the copy whose files the tests edit.
    const mod = (rel) => import(pathToFileURL(path.join(a.pkg, "cli", "lib", rel)).href);
    lib = { ...(await mod("project.mjs")), ...(await mod("hash.mjs")) };
  });
  const hashA = () => lib.renderHash(lib.resolveEpisode(lib.loadProject(a.project), ID));
  // Change a file for one hash, then put it back.
  const withEdit = (file, edit, fn) => {
    const original = readFileSync(file);
    try {
      writeFileSync(file, edit(original.toString("utf8")));
      return fn();
    } finally {
      writeFileSync(file, original);
    }
  };
  const lexicon = () => path.join(a.project, "lexicon.json");
  const addWord = (word, phonemes) => (text) => {
    const lex = JSON.parse(text);
    lex.words[word] = phonemes;
    return JSON.stringify(lex, null, 2);
  };

  test("is 16 hex characters, stable, and the same in another checkout", () => {
    const h = hashA();
    assert.match(h, /^[0-9a-f]{16}$/);
    assert.equal(hashA(), h);
    const r = runCli(["hash", ID, "--project", b.project], { cli: path.join(b.pkg, "cli", "avatars.mjs") });
    assert.equal(r.status, 0, outputOf(r));
    assert.equal(r.stdout.trim(), `${ID}-${h}`);
  });

  test("changes with the episode's own files", () => {
    const h = hashA();
    const page = path.join(a.project, "episodes", ID, "index.html");
    assert.notEqual(withEdit(page, (s) => `${s}<!-- a change -->\n`, hashA), h);
    const extra = path.join(a.project, "episodes", ID, "notes.txt");
    writeFileSync(extra, "a file the episode keeps\n");
    try {
      assert.notEqual(hashA(), h);
    } finally {
      rmSync(extra);
    }
    assert.equal(hashA(), h);
  });

  test("changes with a lexicon entry its lines use, not with an unused one", () => {
    const h = hashA();
    // "blazer" is in the episode's narration, "zyzzyva" in none.
    assert.notEqual(withEdit(lexicon(), addWord("blazer", "blˈeɪzɚ"), hashA), h);
    assert.equal(withEdit(lexicon(), addWord("zyzzyva", "zˈɪzɪvə"), hashA), h);
  });

  test("changes with a library file the bundle includes, not with one it leaves out", () => {
    const h = hashA();
    const comment = (s) => `${s}\n// a change\n`;
    // The episode's host wears the blazer, not the hoodie.
    assert.notEqual(withEdit(path.join(a.pkg, "parts", "tops", "blazer", "part.js"), comment, hashA), h);
    assert.notEqual(withEdit(path.join(a.pkg, "scenes", "talk", "talk.css"), (s) => `${s}\n/* a change */\n`, hashA), h);
    const addToken = (s) => JSON.stringify(Object.assign(JSON.parse(s), { "test-only": { $value: 1 } }));
    assert.notEqual(withEdit(path.join(a.pkg, "themes", "daylight", "theme.tokens.json"), addToken, hashA), h, "the episode's theme");
    assert.equal(withEdit(path.join(a.pkg, "themes", "midnight", "theme.tokens.json"), addToken, hashA), h, "another theme");
    assert.equal(withEdit(path.join(a.pkg, "parts", "tops", "hoodie", "part.js"), comment, hashA), h);
    assert.equal(withEdit(path.join(a.pkg, "scenes", "talk", "README.md"), (s) => `${s}\nA change.\n`, hashA), h);
  });

  test("ignores vendor/, assets/voice/, snapshots/ and other generated files", () => {
    const h = hashA();
    const dir = path.join(a.project, "episodes", ID);
    for (const rel of ["vendor/extra.js", "assets/voice/intro.json", "assets/voice/lines.js", "snapshots/contact-sheet-1.jpg", "renders/x.mp4", ".hyperframes/cache", "node_modules/x/index.js"]) {
      mkdirSync(path.dirname(path.join(dir, rel)), { recursive: true });
      writeFileSync(path.join(dir, rel), `generated ${rel}\n`);
    }
    assert.equal(hashA(), h);
    assert.deepEqual(episodeFiles(dir), ["episode.json", "hyperframes.json", "index.html", "script.json"]);
  });
});
